export type RemoveLiquidityInput<
  TAccountLp extends InstructionSignerInput = InstructionSignerInput,
  TAccountMarketState extends InstructionAccountInput = InstructionAccountInput,
  TAccountLpMint extends InstructionAccountInput = InstructionAccountInput,
  TAccountLpShares extends InstructionAccountInput = InstructionAccountInput,
  TAccountLpToken0 extends InstructionAccountInput = InstructionAccountInput,
  TAccountLpToken1 extends InstructionAccountInput = InstructionAccountInput,
  TAccountVault0 extends InstructionAccountInput = InstructionAccountInput,
  TAccountVault1 extends InstructionAccountInput = InstructionAccountInput,
  TAccountMint0 extends InstructionAccountInput = InstructionAccountInput,
  TAccountMint1 extends InstructionAccountInput = InstructionAccountInput,
  TAccountAuthority extends InstructionAccountInput = InstructionAccountInput,
  TAccountCtokenAccount extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountCollateralMint extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountLpCtoken extends InstructionAccountInput = InstructionAccountInput,
  TAccountTokenProgram0 extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountTokenProgram1 extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountTokenProgram extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountAssociatedTokenProgram extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountSystemProgram extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountKlendProgram extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountReserve extends InstructionAccountInput = InstructionAccountInput,
  TAccountLendingMarket extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountLendingMarketAuthority extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountReserveLiquiditySupply extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountInstructionsSysvar extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountReserveCollateralMint extends InstructionAccountInput =
    InstructionAccountInput,
> = {
  /**
   * The LP, who burns their shares and pays for their cToken account if an in-kind removal
   * creates it.
   */
  lp: TAccountLp;
  marketState: TAccountMarketState;
  lpMint: TAccountLpMint;
  /** The token account of the LP mint the shares are burned from, which the LP owns. */
  lpShares: TAccountLpShares;
  lpToken0: TAccountLpToken0;
  lpToken1: TAccountLpToken1;
  vault0: TAccountVault0;
  vault1: TAccountVault1;
  mint0: TAccountMint0;
  mint1: TAccountMint1;
  authority: TAccountAuthority;
  ctokenAccount: TAccountCtokenAccount;
  /**
   * The reserve's collateral (cToken) mint, an SPL Token mint, read-only, so an in-kind
   * removal never write-locks the mint every Kamino user of the reserve shares; a cash removal
   * passes it again, writable, among the Kamino accounts.
   */
  collateralMint: TAccountCollateralMint;
  /**
   * removal pays the cTokens, created there if missing; checked only in kind, since a cash
   * removal never touches it.
   */
  lpCtoken: TAccountLpCtoken;
  tokenProgram0: TAccountTokenProgram0;
  tokenProgram1: TAccountTokenProgram1;
  /** SPL Token, the program of the LP mint, the lent mint and every cToken mint. */
  tokenProgram?: TAccountTokenProgram;
  associatedTokenProgram?: TAccountAssociatedTokenProgram;
  systemProgram?: TAccountSystemProgram;
  /**
   * For a removal in cash, the lent mint's Kamino accounts, each checked before any is
   * passed to klend ([`KaminoAccounts::check`]); left out in kind.
   */
  klendProgram?: TAccountKlendProgram;
  reserve?: TAccountReserve;
  lendingMarket?: TAccountLendingMarket;
  lendingMarketAuthority?: TAccountLendingMarketAuthority;
  reserveLiquiditySupply?: TAccountReserveLiquiditySupply;
  instructionsSysvar?: TAccountInstructionsSysvar;
  /** supply; checked against the lent mint's entry in `LENT_MINTS`. */
  reserveCollateralMint?: TAccountReserveCollateralMint;
  lpArg: RemoveLiquidityInstructionDataArgs["lp"];
  minOther: RemoveLiquidityInstructionDataArgs["minOther"];
  minLent: RemoveLiquidityInstructionDataArgs["minLent"];
  inKind: RemoveLiquidityInstructionDataArgs["inKind"];
};

